from pathlib import Path
import html,json,xml.etree.ElementTree as ET
r=Path(__file__).resolve().parent.parent
copy=json.loads((r/'outputs/torekh-what-to-expect-copy.json').read_text(encoding='utf-8'))
assets=json.loads((r/'outputs/torekh-voting-illustration-assets.json').read_text(encoding='utf-8'))
e=lambda s:html.escape(s,quote=True)
faq='https://www.gov.il/he/pages/elections_faq'
locator='https://www.gov.il/apps/moin/bocharim/'
css='''#wrapwrap>header,#wrapwrap>footer,.o_social_push_notifications_permission_request{display:none!important}body{background:#f6f4ed}#torekh-expect{--ink:#183d3b;--line:#cad1c5;color:var(--ink);background:#f6f4ed;font:17px/1.7 system-ui,Arial,sans-serif;min-height:100vh}#torekh-expect *{box-sizing:border-box}#torekh-expect [hidden]{display:none!important}#torekh-expect a{color:#215c51;text-underline-offset:4px}#torekh-expect a:focus-visible,#torekh-expect summary:focus-visible{outline:3px solid #ae641f;outline-offset:4px}#torekh-expect .expect-wrap{max-width:960px;margin:auto;padding:24px}#torekh-expect nav{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;border-bottom:1px solid var(--line);padding-bottom:16px}#torekh-expect nav a{display:inline-flex;align-items:center;min-height:44px}#torekh-expect .expect-langs{display:flex;gap:8px;flex-wrap:wrap}#torekh-expect .expect-langs a{padding:8px 12px;border:1px solid var(--line);border-radius:999px}#torekh-expect .expect-langs a[aria-current=page]{background:#e4eadc;font-weight:700}#torekh-expect h1{font-size:clamp(34px,5vw,54px);line-height:1.2;margin:12px 0 18px;color:var(--ink)}#torekh-expect h2{font-size:26px;line-height:1.4;color:var(--ink);margin:0 0 15px}#torekh-expect p{margin:0 0 15px}#torekh-expect .expect-hero{padding:36px 0 24px;max-width:750px}#torekh-expect .eyebrow{font-size:13px}#torekh-expect .expect-before{border:1px solid #a8b9ab;border-radius:14px;padding:25px;background:#e8ecdf;margin-bottom:28px}#torekh-expect ul{padding-inline-start:24px;margin:0 0 18px}#torekh-expect li{margin:10px 0}#torekh-expect .expect-links{display:flex;gap:16px;flex-wrap:wrap}#torekh-expect .expect-links a{display:inline-flex;align-items:center;min-height:44px}#torekh-expect .expect-step{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:26px;align-items:center;border-top:1px solid var(--line);padding:28px 0;scroll-margin-top:24px}#torekh-expect .expect-step.no-art{grid-template-columns:1fr}#torekh-expect .expect-step img{display:block;width:100%;height:auto;aspect-ratio:3/2;object-fit:contain;mix-blend-mode:multiply}#torekh-expect .expect-step-no{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;margin-inline-end:10px;border:1px solid #a8b9ab;border-radius:50%;font-size:19px;vertical-align:middle}#torekh-expect .expect-illustration-note{font-size:12px;color:#52685d;line-height:1.6}#torekh-expect .expect-faqs{border-top:1px solid var(--line);padding:28px 0}#torekh-expect details{border-bottom:1px solid var(--line);padding:8px 0}#torekh-expect summary{cursor:pointer;min-height:48px;padding:10px 0;font-weight:600}#torekh-expect details p{font-size:16px;padding:0 0 8px}#torekh-expect .expect-footer{font-size:13px;border-top:1px solid var(--line);padding:24px 0}#torekh-expect .expect-footer h2{font-size:20px}@media(max-width:650px){#torekh-expect{font-size:16px}#torekh-expect .expect-wrap{padding:18px}#torekh-expect .expect-hero{padding-top:26px}#torekh-expect h2{font-size:23px}#torekh-expect .expect-before{padding:19px}#torekh-expect .expect-step{grid-template-columns:1fr;gap:8px;padding:24px 0}#torekh-expect .expect-step img{max-width:360px;justify-self:center}#torekh-expect .expect-step-no{width:32px;height:32px;font-size:17px}}'''
parts=[]
for lang,c in copy.items():
    guide=f'https://www.torekh.org/{lang}?lang={lang}'
    direction='ltr' if lang=='en' else 'rtl'
    section=f'<article data-expect-lang="{lang}" lang="{lang}" dir="{direction}"'+(' hidden="hidden"' if lang!='en' else '')+'>'
    section+=f'<nav aria-label="{e(c["navigation"])}"><a href="{e(guide)}">{e(c["back"])}</a><div class="expect-langs" aria-label="Language"><a data-lang="ar" lang="ar" href="/ar/what-to-expect?lang=ar">العربية</a><a data-lang="he" lang="he" href="/he/what-to-expect?lang=he">עברית</a><a data-lang="en" lang="en" href="/en/what-to-expect?lang=en">English</a></div></nav>'
    section+=f'<header class="expect-hero"><p class="eyebrow">{e(c["title"])}</p><h1>{e(c["heading"])}</h1><p>{e(c["intro"])}</p></header>'
    section+=f'<section class="expect-before"><h2>{e(c["beforeTitle"])}</h2><ul>'+''.join(f'<li>{e(item)}</li>' for item in c['before'])+f'</ul><div class="expect-links"><a href="{e(locator)}" target="_blank" rel="noopener noreferrer">{e(c["findStation"])}</a><a href="{faq}" target="_blank" rel="noopener noreferrer">{e(c["officialFaq"])}</a></div></section>'
    for i,step in enumerate(c['steps'],1):
        asset=[None,'booth','trays','box'][i-1]
        anchor=f' id="first-vote-{lang}"' if i==1 else ''
        section+=f'<section{anchor} class="expect-step'+(' no-art' if not asset else '')+f'"><div><h2><span class="expect-step-no">{i}</span>{e(step[0])}</h2><p>{e(step[1])}</p></div>'
        if asset:section+=f'<img src="{assets[asset]}" alt="{e(step[2])}" width="480" height="320" loading="lazy" decoding="async"/>'
        section+='</section>'
    section+=f'<p class="expect-illustration-note">{e(c["illustrationNote"])}</p><section class="expect-faqs"><h2>{e(c["questionsTitle"])}</h2>'
    section+=''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in c['questions'])+'</section>'
    section+=f'<footer class="expect-footer"><h2>{e(c["sourcesTitle"])}</h2><p>{e(c["sourcesNote"])}</p><div class="expect-links"><a href="{faq}" target="_blank" rel="noopener noreferrer">{e(c["officialFaq"])}</a><a href="{e(locator)}" target="_blank" rel="noopener noreferrer">{e(c["findStation"])}</a></div><p>{e(c["checked"])}</p></footer></article>'
    parts.append(section)
js='''(()=>{const root=document.getElementById('torekh-expect');const requested=new URLSearchParams(location.search).get('lang')||document.documentElement.lang;const short=(requested||'en').slice(0,2);const lang=['ar','he','en'].includes(short)?short:'en';root.querySelectorAll('[data-expect-lang]').forEach(el=>{el.hidden=el.dataset.expectLang!==lang});root.querySelectorAll('[data-lang]').forEach(el=>{if(el.dataset.lang===lang)el.setAttribute('aria-current','page')});const selected=root.querySelector('[data-expect-lang="'+lang+'"]');root.setAttribute('dir',selected.dir);root.setAttribute('lang',lang);const names={ar:'التصويت للمرة الأولى: ماذا تتوقعون؟',he:'מצביעים בפעם הראשונה: למה לצפות?',en:'Your first time voting: what to expect'};document.title=names[lang];})();'''
markup=f'<style>{css}</style><main id="torekh-expect"><div class="expect-wrap">'+''.join(parts)+'</div></main>'
body=markup+f'<script>{js}</script>'
(r/'outputs/torekh-what-to-expect.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Your first time voting: what to expect</title><meta name="description" content="A simple illustrated guide to voting: find your station, bring ID, choose one slip and put the envelope in the ballot box."></head><body>'+body+'</body></html>',encoding='utf-8')
xml='<t t-name="website.what-to-expect"><t t-call="website.layout"><div id="wrap" class="oe_structure" t-translation="off">'+markup+'<script>'+html.escape(js,quote=False)+'</script></div></t></t>'
ET.fromstring(xml)
(r/'work/expect-page-first-voter.xml').write_text(xml,encoding='utf-8')
assert len(parts)==3
for prohibited in ['public beta','planned','project','github','roadmap','AI-generated']:
    assert prohibited.lower() not in body.lower(),prohibited
print('Built a practical four-step voting guide in Arabic, Hebrew and English, with official sources and no project description.')
